/**
 * Client for the FB_Exchange_Rates provider (latest FX rates).
 *
 * All traffic goes through the Named Credential callout:FB_Exchange_Rates, so
 * authentication and base URL are managed in Setup, not in code.
 */
public class ExchangeRateClient {

    private static final String ENDPOINT_PATH = 'callout:FB_Exchange_Rates/v1/latest';
    private static final String CODE_PATTERN = '[A-Z]{3}';

    public class ExchangeRateException extends Exception {}

    /**
     * Returns a map from each requested (normalised) quote currency code to its rate
     * relative to the normalised base currency.
     *
     * @throws ExchangeRateException for invalid input, HTTP failures (non-200 after
     *         one retry on 503), callout failures, unparseable bodies or missing rates.
     */
    public static Map<String, Decimal> getRates(String baseCurrency, Set<String> quoteCurrencies) {
        // Validate and normalise input before any callout is made.
        String base = normaliseCode(baseCurrency);

        if (quoteCurrencies == null || quoteCurrencies.isEmpty()) {
            throw new ExchangeRateException('At least one quote currency code is required.');
        }

        Set<String> quotes = new Set<String>();
        for (String quote : quoteCurrencies) {
            quotes.add(normaliseCode(quote));
        }

        // Deterministic symbols parameter (sorted, comma-separated).
        List<String> sortedQuotes = new List<String>(quotes);
        sortedQuotes.sort();
        String symbols = String.join(sortedQuotes, ',');

        HttpResponse response = sendWithRetryOn503(base, symbols);

        Integer statusCode = response.getStatusCode();
        if (statusCode != 200) {
            throw new ExchangeRateException(
                'Exchange rate request failed with HTTP status ' + statusCode + '.'
            );
        }

        return parseRates(response.getBody(), sortedQuotes);
    }

    // ------------------------------------------------------------------
    // Helpers
    // ------------------------------------------------------------------

    private static String normaliseCode(String code) {
        if (code == null) {
            throw new ExchangeRateException('Currency code must not be null.');
        }
        String normalised = code.trim().toUpperCase();
        // Pattern.matches requires the whole input to match the regex.
        if (!Pattern.matches(CODE_PATTERN, normalised)) {
            throw new ExchangeRateException(
                'Invalid currency code "' + code + '": must be exactly three letters A-Z.'
            );
        }
        return normalised;
    }

    /**
     * Sends the request. If the first response is 503, sends one identical retry.
     * Returns the final response (which the caller checks for status 200).
     */
    private static HttpResponse sendWithRetryOn503(String base, String symbols) {
        HttpResponse response = send(base, symbols);
        if (response.getStatusCode() == 503) {
            response = send(base, symbols);
        }
        return response;
    }

    private static HttpResponse send(String base, String symbols) {
        HttpRequest req = new HttpRequest();
        req.setEndpoint(ENDPOINT_PATH
            + '?base=' + EncodingUtil.urlEncode(base, 'UTF-8')
            + '&symbols=' + EncodingUtil.urlEncode(symbols, 'UTF-8'));
        req.setMethod('GET');
        req.setHeader('Accept', 'application/json');

        try {
            return new Http().send(req);
        } catch (CalloutException e) {
            throw new ExchangeRateException('Exchange rate callout failed: ' + e.getMessage());
        }
    }

    private static Map<String, Decimal> parseRates(String body, List<String> requestedCodes) {
        Object parsed;
        try {
            parsed = JSON.deserializeUntyped(body);
        } catch (Exception e) {
            throw new ExchangeRateException('Exchange rate response body could not be parsed as JSON.');
        }

        if (!(parsed instanceof Map<String, Object>)) {
            throw new ExchangeRateException('Exchange rate response body is not a JSON object.');
        }

        Map<String, Object> root = (Map<String, Object>) parsed;
        Object ratesObj = root.get('rates');
        if (!(ratesObj instanceof Map<String, Object>)) {
            throw new ExchangeRateException('Exchange rate response does not contain a "rates" object.');
        }

        Map<String, Object> rawRates = (Map<String, Object>) ratesObj;
        Map<String, Decimal> result = new Map<String, Decimal>();

        for (String code : requestedCodes) {
            if (!rawRates.containsKey(code)) {
                throw new ExchangeRateException('No rate returned for currency "' + code + '".');
            }
            result.put(code, toDecimal(rawRates.get(code), code));
        }

        return result;
    }

    private static Decimal toDecimal(Object value, String code) {
        if (value == null) {
            throw new ExchangeRateException('Rate for currency "' + code + '" is null.');
        }
        try {
            return Decimal.valueOf(String.valueOf(value));
        } catch (Exception e) {
            throw new ExchangeRateException('Rate for currency "' + code + '" is not a valid number.');
        }
    }
}
