        // Rounding per opportunity gives 6.66; rounding only the total would give 6.67.
        List<Opportunity> opps = new List<Opportunity>{
            newOpp(accountId, 'Prospecting', 10, 33.33),
            newOpp(accountId, 'Prospecting', 10, 33.33)
