        mocks.when(selector.selectOpenByAccountIds(accountIds)).thenReturn(opps);
        mocks.stopStubbing();

        Map<String, Decimal> totals = OpportunityForecastService.weightedAmountByStage(accountIds);

        Decimal prospecting = totals.get('Prospecting');
        System.assertEquals(6.66, prospecting, 'Each opportunity must be rounded to 2 decimals before summing');
