            new Opportunity(Id = onCutoff, StageName = 'Prospecting', CloseDate = CUTOFF),
            new Opportunity(Id = future, StageName = 'Prospecting', CloseDate = Date.newInstance(2025, 1, 1)),
            new Opportunity(Id = closedWon, StageName = 'Closed Won', CloseDate = Date.newInstance(2023, 1, 1)),
            new Opportunity(Id = closedLost, StageName = 'Closed Lost', CloseDate = Date.newInstance(2023, 1, 1))
