public class Application {

    // Unit of Work: commit order matters. Accounts first, then Contacts and Opportunities
    // (both reference Account), then OpportunityContactRoles (reference Opportunity and Contact).
    public static final fflib_Application.UnitOfWorkFactory UnitOfWork = new fflib_Application.UnitOfWorkFactory(
        new List<SObjectType>{
            Account.SObjectType,
            Contact.SObjectType,
            Opportunity.SObjectType,
            OpportunityContactRole.SObjectType
        }
    );

    // Service layer: interface to implementation bindings
    public static final fflib_Application.ServiceFactory Service = new fflib_Application.ServiceFactory(
        new Map<Type, Type>{
            IAccountsService.class => AccountsServiceImpl.class
        }
    );

    // Selector layer: SObjectType to selector bindings
