public with sharing class Opportunities extends fflib_SObjectDomain {

    private static final String CLOSED_WON_STAGE = 'Closed Won';
    private static final String MSG_NEGATIVE_AMOUNT = 'Amount cannot be negative.';
    private static final String MSG_WON_AMOUNT_LOCKED = 'Amount cannot change on a won opportunity.';

    public Opportunities(List<SObject> sObjectList) {
        super(sObjectList);
    }

    /**
     * Insert validation: Amount must not be negative.
     * Runs in the before-insert phase via the fflib framework.
     */
    public override void onValidate() {
        for (SObject record : Records) {
            Opportunity opp = (Opportunity) record;
            if (opp.Amount != null && opp.Amount < 0) {
                rejectAmount(opp, MSG_NEGATIVE_AMOUNT);
            }
        }
    }

    /**
     * Update validation:
     *  1. Amount must not be negative.
     *  2. Amount cannot change if the opportunity was already Closed Won before this update.
     *     Moving an opportunity to Closed Won while changing Amount in the same update is allowed,
     *     because the prior stage was not Closed Won.
     * Uses only the Trigger.old snapshot passed by fflib; no SOQL.
     */
    public override void onValidate(Map<Id, SObject> existingRecords) {
        for (SObject record : Records) {
            Opportunity opp = (Opportunity) record;

            if (opp.Amount != null && opp.Amount < 0) {
                rejectAmount(opp, MSG_NEGATIVE_AMOUNT);
            }

            Opportunity existing = (Opportunity) existingRecords.get(opp.Id);
            if (existing == null) {
                continue;
            }

            if (existing.StageName == CLOSED_WON_STAGE && opp.Amount != existing.Amount) {
                rejectAmount(opp, MSG_WON_AMOUNT_LOCKED);
            }
        }
    }

    /**
     * Records the error through the fflib helper (so it appears in fflib_SObjectDomain.Errors)
     * and blocks the save of this record only, by attaching the error to the Amount field.
     */
    private void rejectAmount(Opportunity opp, String message) {
        error(message, opp, Opportunity.Amount);
        opp.addError(Opportunity.Amount, message);
    }

    public class Constructor implements fflib_SObjectDomain.IConstructable {
        public fflib_SObjectDomain construct(List<SObject> sObjectList) {
            return new Opportunities(sObjectList);
        }
    }
}
