public inherited sharing class AccountsSelector extends fflib_SObjectSelector {

    private static final String CREDIT_REVIEW_FIELD_SET = 'Credit_Review';

    public AccountsSelector() {
        // USER_MODE: every query from this selector runs WITH USER_MODE, so the platform
        // enforces the running user's object, field and sharing access.
        // includeFieldSetFields is false because the field set is merged explicitly below.
        super(false, fflib_SObjectSelector.DataAccess.USER_MODE);
    }

    public Schema.SObjectType getSObjectType() {
        return Account.SObjectType;
    }

    public List<Schema.SObjectField> getSObjectFieldList() {
        Map<String, Schema.SObjectField> fieldsByName = new Map<String, Schema.SObjectField>();
        Map<String, Schema.SObjectField> accountFields = Schema.SObjectType.Account.fields.getMap();

        addFieldIfPresent(fieldsByName, accountFields, 'Id');
        addFieldIfPresent(fieldsByName, accountFields, 'Name');
        addFieldIfPresent(fieldsByName, accountFields, 'Industry');

        // Field set is read at runtime so admins can change its members without code changes.
        Schema.FieldSet creditReviewFieldSet = getCreditReviewFieldSet();
        if (creditReviewFieldSet != null) {
            for (Schema.FieldSetMember member : creditReviewFieldSet.getFields()) {
                addFieldIfPresent(fieldsByName, accountFields, member.getFieldPath());
            }
        }

        return fieldsByName.values();
    }

    public List<Account> selectById(Set<Id> accountIds) {
        return (List<Account>) selectSObjectsById(accountIds);
    }

    public List<Account> selectByIdWithContacts(Set<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return new List<Account>();
        }

        String soql =
            'SELECT ' + String.join(toFieldNames(getSObjectFieldList()), ', ') +
            ', (SELECT ' + String.join(toFieldNames(new ContactsSelector().getSObjectFieldList()), ', ') +
            ' FROM Contacts)' +
            ' FROM Account' +
            ' WHERE Id IN :accountIds' +
            ' WITH USER_MODE';

        return (List<Account>) Database.query(soql);
    }

    private static Schema.FieldSet getCreditReviewFieldSet() {
        Map<String, Schema.FieldSet> fieldSets = Schema.SObjectType.Account.fieldSets.getMap();
        return fieldSets.get(CREDIT_REVIEW_FIELD_SET);
    }

    private static void addFieldIfPresent(
        Map<String, Schema.SObjectField> fieldsByName,
        Map<String, Schema.SObjectField> accountFields,
        String fieldPath
    ) {
        if (String.isBlank(fieldPath)) {
            return;
        }
        Schema.SObjectField field = accountFields.get(fieldPath.toLowerCase());
        if (field != null) {
            fieldsByName.put(field.getDescribe().getName().toLowerCase(), field);
        }
    }

    private static List<String> toFieldNames(List<Schema.SObjectField> fields) {
        List<String> names = new List<String>();
        for (Schema.SObjectField field : fields) {
            names.add(field.getDescribe().getName());
        }
        return names;
    }
}
