import ACCOUNT_SELECTED_CHANNEL from '@salesforce/messageChannel/Account_Selected__c';

export default class AccountDetailsPanel extends LightningElement {
    recordId = null;
    subscription = null;
    subscriptionActive = false;
    isConnected = false;
    messageContext;

    @wire(MessageContext)
    wiredMessageContext(context) {
        this.messageContext = context;
        // If the wire resolves after insertion and we are not yet subscribed, subscribe now.
        if (this.isConnected && !this.subscriptionActive) {
            this.subscribeToMessages();
        }
    }

    get hasSelection() {
        return !!this.recordId;
    }

    connectedCallback() {
        this.isConnected = true;
        this.subscribeToMessages();
    }

    disconnectedCallback() {
        this.isConnected = false;
        this.unsubscribeFromMessages();
    }

    subscribeToMessages() {
        // Never hold more than one subscription.
        if (this.subscriptionActive) {
            return;
        }
        this.subscription = subscribe(
            this.messageContext,
            ACCOUNT_SELECTED_CHANNEL,
            (message) => this.handleMessage(message),
            { scope: APPLICATION_SCOPE }
        );
        this.subscriptionActive = true;
    }

    unsubscribeFromMessages() {
        if (this.subscriptionActive) {
            unsubscribe(this.subscription);
            this.subscription = null;
            this.subscriptionActive = false;
        }
    }

    handleMessage(message) {
        this.recordId = message && message.recordId ? message.recordId : null;
    }

    handleClear() {
        publish(this.messageContext, ACCOUNT_SELECTED_CHANNEL, { recordId: null });
    }
}
