```apex
/**
 * Routes website gifts through NPSP's Data Import engine (BDI) so that NPSP
 * contact matching, household creation and donation processing apply, and
 * each staged npsp__DataImport__c row remains as the audit trail.
 *
 * Processing is synchronous and happens in the calling transaction.
 * Rows NPSP rejects (or that fail to stage) do not stop other rows.
 */
public with sharing class GiftImportService {

    public class WebGift {
        public String firstName;
        public String lastName;
        public String email;        // the donor's personal email
        public Decimal amount;
        public Date giftDate;
    }

    public class ImportResult {
        public Boolean success;
        public Id contactId;        // the matched or created contact
        public Id opportunityId;    // the created donation
        public String errorMessage; // NPSP's failure information when success is false
    }

    private static final String STATUS_READY = 'Ready';
    private static final String STATUS_IMPORTED = 'Imported';

    public static List<ImportResult> importGifts(List<WebGift> gifts) {
        List<ImportResult> results = new List<ImportResult>();
        if (gifts == null || gifts.isEmpty()) {
            return results;
        }

        // Pre-populate results in input order; filled in below.
        for (Integer i = 0; i < gifts.size(); i++) {
            ImportResult r = new ImportResult();
            r.success = false;
            results.add(r);
        }

        // 1. Stage one Data Import row per gift.
        List<npsp__DataImport__c> staged = new List<npsp__DataImport__c>();
        for (WebGift g : gifts) {
            staged.add(buildDataImport(g));
        }

        // 2. Insert staging rows. Partial failure must not stop the others.
        List<Database.SaveResult> insertResults = Database.insert(staged, false);
        Map<Integer, String> stageErrors = new Map<Integer, String>();
        List<npsp__DataImport__c> toProcess = new List<npsp__DataImport__c>();
        List<Integer> toProcessIdx = new List<Integer>();
        for (Integer i = 0; i < insertResults.size(); i++) {
            Database.SaveResult sr = insertResults[i];
            if (sr.isSuccess()) {
                toProcess.add(staged[i]);
                toProcessIdx.add(i);
            } else {
                stageErrors.put(i, joinErrors(sr.getErrors()));
            }
        }

        // 3. Process synchronously through NPSP's data import API.
        if (!toProcess.isEmpty()) {
            npsp__Data_Import_Settings__c diSettings = npsp__Data_Import_Settings__c.getInstance();
            if (diSettings == null) {
                diSettings = new npsp__Data_Import_Settings__c();
            }

            // Mark the staged rows as ready for NPSP to process.
            for (npsp__DataImport__c di : toProcess) {
                di.npsp__Status__c = STATUS_READY;
            }

            String processingError = null;
            try {
                npsp.BDI_DataImport_API.processDataImportRecords(diSettings, toProcess, false);
            } catch (Exception e) {
                processingError = e.getMessage();
            }

            // 4. Read NPSP's results back from the staged rows.
            Set<Id> ids = new Set<Id>();
            for (npsp__DataImport__c di : toProcess) {
                ids.add(di.Id);
            }
            Map<Id, npsp__DataImport__c> processed = new Map<Id, npsp__DataImport__c>([
                SELECT Id, npsp__Status__c, npsp__Contact1Imported__c,
                       npsp__DonationImported__c, npsp__FailureInformation__c
                FROM npsp__DataImport__c
                WHERE Id IN :ids
            ]);

            for (Integer k = 0; k < toProcess.size(); k++) {
                Integer idx = toProcessIdx[k];
                npsp__DataImport__c di = processed.get(toProcess[k].Id);
                ImportResult r = results[idx];

                if (di == null) {
                    r.success = false;
                    r.errorMessage = processingError != null
                        ? processingError
                        : 'Data Import row was not processed.';
                    continue;
                }

                Boolean imported = di.npsp__Status__c == STATUS_IMPORTED;
                r.success = imported;
                r.contactId = di.npsp__Contact1Imported__c;
                r.opportunityId = di.npsp__DonationImported__c;
                if (!imported) {
                    r.contactId = null;
                    r.opportunityId = null;
                    r.errorMessage = String.isNotBlank(di.npsp__FailureInformation__c)
                        ? di.npsp__FailureInformation__c
                        : (processingError != null ? processingError : 'NPSP did not import this gift.');
                }
            }
        }

        // Rows that failed to stage.
        for (Integer i : stageErrors.keySet()) {
            ImportResult r = results[i];
            r.success = false;
            r.errorMessage = stageErrors.get(i);
        }

        return results;
    }

    private static npsp__DataImport__c buildDataImport(WebGift g) {
        npsp__DataImport__c di = new npsp__DataImport__c();
        if (g == null) {
            return di; // NPSP will reject; the row is kept as an audit record.
        }
        di.npsp__Contact1_Firstname__c = g.firstName;
        di.npsp__Contact1_Lastname__c = g.lastName;
        di.npsp__Contact1_Personal_Email__c = g.email;
        di.npsp__Donation_Amount__c = g.amount;
        di.npsp__Donation_Date__c = g.giftDate;
        di.npsp__Donation_Donor__c = 'Contact1';
        return di;
    }

    private static String joinErrors(List<Database.Error> errors) {
        List<String> messages = new List<String>();
        for (Database.Error err : errors) {
            messages.add(err.getMessage());
        }
        return String.join(messages, '; ');
    }
}
