```apex
public with sharing class SoftCreditService {

    public class SoftCreditException extends Exception {}

    public class SoftCreditRequest {
        public Id opportunityId;
        public Id contactId;
        public Decimal amount;
        public String role;
    }

    /**
     * Ensures each request's contact has exactly one OpportunityContactRole on the
     * opportunity with the requested role, and exactly one NPSP partial soft credit
     * for that contact/opportunity with the requested amount and role.
     *
     * All validation and reads happen before any DML. DML is performed in three
     * bulkified statements: upsert contact roles, delete surplus records, upsert
     * partial soft credits.
     *
     * SOQL: 4 queries (opportunities, contacts, contact roles, partial soft credits).
     * DML: 3 statements, regardless of request count.
     */
    public static void addPartialSoftCredits(List<SoftCreditRequest> requests) {
        if (requests == null || requests.isEmpty()) {
            return;
        }

        // ---------- Pass 1: structural validation (no SOQL) ----------
        Set<Id> oppIds = new Set<Id>();
        Set<Id> contactIds = new Set<Id>();
        Set<String> seenKeys = new Set<String>();

        for (SoftCreditRequest r : requests) {
            if (r == null) {
                throw new SoftCreditException('Null request in input list.');
            }
            if (r.opportunityId == null || r.contactId == null) {
                throw new SoftCreditException('Each request requires an opportunityId and a contactId.');
            }
            if (r.amount == null || r.amount <= 0) {
                throw new SoftCreditException('Soft credit amount must be a positive value. Contact: ' + r.contactId);
            }
            if (String.isBlank(r.role)) {
                throw new SoftCreditException('Soft credit role is required. Contact: ' + r.contactId);
            }
            String key = pairKey(r.opportunityId, r.contactId);
            if (!seenKeys.add(key)) {
                throw new SoftCreditException('Duplicate opportunity/contact pair in request: ' + key);
            }
            oppIds.add(r.opportunityId);
            contactIds.add(r.contactId);
        }

        // ---------- Reads (4 SOQL) ----------
        Map<Id, Opportunity> oppById = new Map<Id, Opportunity>([
            SELECT Id, Amount, npsp__Primary_Contact__c
            FROM Opportunity
            WHERE Id IN :oppIds
        ]);

        Map<Id, Contact> contactById = new Map<Id, Contact>([
            SELECT Id
            FROM Contact
            WHERE Id IN :contactIds
        ]);

        Map<String, List<OpportunityContactRole>> ocrByKey = new Map<String, List<OpportunityContactRole>>();
        for (OpportunityContactRole ocr : [
            SELECT Id, OpportunityId, ContactId, Role
            FROM OpportunityContactRole
            WHERE OpportunityId IN :oppIds
              AND ContactId IN :contactIds
        ]) {
            String key = pairKey(ocr.OpportunityId, ocr.ContactId);
            if (!ocrByKey.containsKey(key)) {
                ocrByKey.put(key, new List<OpportunityContactRole>());
            }
            ocrByKey.get(key).add(ocr);
        }

        Map<String, List<npsp__Partial_Soft_Credit__c>> pscByKey = new Map<String, List<npsp__Partial_Soft_Credit__c>>();
        for (npsp__Partial_Soft_Credit__c psc : [
            SELECT Id, npsp__Opportunity__c, npsp__Contact__c
            FROM npsp__Partial_Soft_Credit__c
            WHERE npsp__Opportunity__c IN :oppIds
              AND npsp__Contact__c IN :contactIds
        ]) {
            String key = pairKey(psc.npsp__Opportunity__c, psc.npsp__Contact__c);
            if (!pscByKey.containsKey(key)) {
                pscByKey.put(key, new List<npsp__Partial_Soft_Credit__c>());
            }
            pscByKey.get(key).add(psc);
        }

        // ---------- Pass 2: business validation (no DML) ----------
        for (SoftCreditRequest r : requests) {
            Opportunity opp = oppById.get(r.opportunityId);
            if (opp == null) {
                throw new SoftCreditException('Opportunity not found: ' + r.opportunityId);
            }
            if (!contactById.containsKey(r.contactId)) {
                throw new SoftCreditException('Contact not found: ' + r.contactId);
            }
            if (opp.npsp__Primary_Contact__c == r.contactId) {
                throw new SoftCreditException(
                    'Contact ' + r.contactId + ' is the primary contact of opportunity ' + r.opportunityId +
                    ' and cannot receive a partial soft credit.'
                );
            }
            if (opp.Amount == null || r.amount > opp.Amount) {
                throw new SoftCreditException(
                    'Soft credit amount ' + r.amount + ' exceeds the opportunity amount for ' + r.opportunityId + '.'
                );
            }
        }

        // ---------- Pass 3: plan changes (no DML) ----------
        List<OpportunityContactRole> ocrUpserts = new List<OpportunityContactRole>();
        Map<String, OpportunityContactRole> keptOcrByKey = new Map<String, OpportunityContactRole>();
        List<SObject> toDelete = new List<SObject>();

        for (SoftCreditRequest r : requests) {
            String key = pairKey(r.opportunityId, r.contactId);
            List<OpportunityContactRole> existing = ocrByKey.get(key);
            OpportunityContactRole keep;

            if (existing != null && !existing.isEmpty()) {
                keep = existing[0];
                keep.Role = r.role;
                for (Integer i = 1; i < existing.size(); i++) {
                    toDelete.add(existing[i]);
                }
            } else {
                keep = new OpportunityContactRole(
                    OpportunityId = r.opportunityId,
                    ContactId = r.contactId,
                    Role = r.role,
                    IsPrimary = false
                );
            }
            ocrUpserts.add(keep);
            keptOcrByKey.put(key, keep);
        }

        // Surplus partial soft credits (keep the first, delete the rest) are queued for deletion.
        Map<String, npsp__Partial_Soft_Credit__c> keptPscByKey = new Map<String, npsp__Partial_Soft_Credit__c>();
        for (SoftCreditRequest r : requests) {
            String key = pairKey(r.opportunityId, r.contactId);
            List<npsp__Partial_Soft_Credit__c> existingPsc = pscByKey.get(key);
            if (existingPsc != null && !existingPsc.isEmpty()) {
                keptPscByKey.put(key, existingPsc[0]);
                for (Integer i = 1; i < existingPsc.size(); i++) {
                    toDelete.add(existingPsc[i]);
                }
            }
        }

        // ---------- DML 1: contact roles (inserts get Ids populated here) ----------
        upsert ocrUpserts;

        // ---------- Build partial soft credits now that contact role Ids exist ----------
        List<npsp__Partial_Soft_Credit__c> pscUpserts = new List<npsp__Partial_Soft_Credit__c>();
        for (SoftCreditRequest r : requests) {
            String key = pairKey(r.opportunityId, r.contactId);
            OpportunityContactRole keptOcr = keptOcrByKey.get(key);
            npsp__Partial_Soft_Credit__c psc = keptPscByKey.get(key);

            if (psc == null) {
                psc = new npsp__Partial_Soft_Credit__c(
                    npsp__Opportunity__c = r.opportunityId,
                    npsp__Contact__c = r.contactId
                );
            }
            psc.npsp__Amount__c = r.amount;
            psc.npsp__Role_Name__c = r.role;
            psc.npsp__Contact_Role_ID__c = keptOcr.Id;
            pscUpserts.add(psc);
        }

        // ---------- DML 2: remove surplus contact roles and partial soft credits ----------
        if (!toDelete.isEmpty()) {
            delete toDelete;
        }

        // ---------- DML 3: partial soft credits ----------
        upsert pscUpserts;
    }

    private static String pairKey(Id opportunityId, Id contactId) {
        return String.valueOf(opportunityId) + ':' + String.valueOf(contactId);
    }
}
