/**
 * Collects Opportunity Ids that must be pushed to the ERP during the current transaction.
 * The Ids are held in transaction-scoped static state and drained by OpportunityErpSyncFinalizer
 * at the end of each DML operation. Nothing is enqueued here, so a DML that the platform chunks
 * (for example 200 + 50) still accumulates into a single set.
 */
public inherited sharing class TA_Opportunity_CollectForErpSync implements TriggerAction.AfterInsert, TriggerAction.AfterUpdate {

    private static Set<Id> pendingOpportunityIds = new Set<Id>();

    public void afterInsert(List<SObject> triggerNew) {
        if (triggerNew == null) {
            return;
        }
        for (SObject record : triggerNew) {
            if (record.Id != null) {
                pendingOpportunityIds.add(record.Id);
            }
        }
    }

    public void afterUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        if (triggerNew == null || triggerOld == null) {
            return;
        }
        Map<Id, SObject> oldById = new Map<Id, SObject>(triggerOld);
        for (SObject record : triggerNew) {
            Opportunity newOpp = (Opportunity) record;
            Opportunity oldOpp = (Opportunity) oldById.get(newOpp.Id);
            if (oldOpp != null && newOpp.StageName != oldOpp.StageName) {
                pendingOpportunityIds.add(newOpp.Id);
            }
        }
    }

    /**
     * Returns the Ids collected so far and resets the collection. Called by the DML finalizer.
     */
    public static Set<Id> drainPendingOpportunityIds() {
        Set<Id> drained = new Set<Id>(pendingOpportunityIds);
        pendingOpportunityIds = new Set<Id>();
        return drained;
    }
}
