/**
 * TAF DML finalizer. The framework calls every finalizer at the end of every DML operation it
 * handles, for any sObject, so this class acts only when Opportunity sync Ids were collected.
 * It enqueues at most one OpportunityErpSyncJob per call and performs no DML.
 */
public inherited sharing class OpportunityErpSyncFinalizer implements TriggerAction.DmlFinalizer {

    public void execute(FinalizerHandler.Context context) {
        Set<Id> opportunityIds = TA_Opportunity_CollectForErpSync.drainPendingOpportunityIds();
        if (opportunityIds.isEmpty()) {
            return;
        }
        System.enqueueJob(new OpportunityErpSyncJob(opportunityIds));
    }
}
