```apex
/**
 * Trigger Action (Trigger Actions Framework 0.3.4) that prevents two Contacts on the same
 * Account from sharing an email address (case-insensitive).
 *
 * Registered via Trigger_Action__mdt for Contact, before insert and before update.
 *
 * Behaviour:
 *  - Contacts without an AccountId or Email are not checked.
 *  - On update, only records whose Email or AccountId changed are checked. Unchanged
 *    records still occupy their (account, email) slot so a changed record cannot collide
 *    with them, but they are never rejected themselves (legacy duplicates do not block
 *    unrelated edits).
 *  - Within one save, the first record in the list that claims an (account, email) pair
 *    is accepted; every later conflicting record is rejected.
 *  - A record never conflicts with itself. Records in the current save are never compared
 *    against their stored database values; their in-memory values are used instead.
 *  - Errors are added per record (addError), so valid records in the same save are unaffected.
 *  - Bulk safe: at most one SOQL query per execution, and none when nothing needs checking.
 *
 * Declared "without sharing" so the rule is enforced regardless of the running user's
 * record visibility.
 */
public without sharing class TA_Contact_PreventDuplicateEmail
        implements TriggerAction.BeforeInsert, TriggerAction.BeforeUpdate {

    @TestVisible
    private static final String DUPLICATE_EMAIL_MESSAGE =
        'Another contact on this account already uses this email address.';

    public void beforeInsert(List<SObject> triggerNew) {
        validate(triggerNew, null);
    }

    public void beforeUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        validate(triggerNew, buildOldById(triggerOld));
    }

    private static Map<Id, Contact> buildOldById(List<SObject> triggerOld) {
        Map<Id, Contact> result = new Map<Id, Contact>();
        if (triggerOld == null) {
            return result;
        }
        for (SObject so : triggerOld) {
            Contact oldC = (Contact) so;
            if (oldC.Id != null) {
                result.put(oldC.Id, oldC);
            }
        }
        return result;
    }

    private static void validate(List<SObject> triggerNew, Map<Id, Contact> oldById) {
        if (triggerNew == null || triggerNew.isEmpty()) {
            return;
        }

        List<Contact> newContacts = new List<Contact>();
        Set<Id> batchIds = new Set<Id>();
        for (SObject so : triggerNew) {
            Contact c = (Contact) so;
            newContacts.add(c);
            if (c.Id != null) {
                batchIds.add(c.Id);
            }
        }

        // Partition: records that must be checked, and unchanged records that only hold a slot.
        List<Integer> checkIndexes = new List<Integer>();
        List<Integer> keeperIndexes = new List<Integer>();
        Set<Id> accountIds = new Set<Id>();
        Set<String> emails = new Set<String>();

        for (Integer i = 0; i < newContacts.size(); i++) {
            Contact c = newContacts[i];
            if (c.AccountId == null || String.isBlank(c.Email)) {
                continue;
            }

            Boolean mustCheck = true;
            if (oldById != null && c.Id != null && oldById.containsKey(c.Id)) {
                Contact oldC = oldById.get(c.Id);
                mustCheck = (c.Email != oldC.Email) || (c.AccountId != oldC.AccountId);
            }

            if (mustCheck) {
                checkIndexes.add(i);
                accountIds.add(c.AccountId);
                emails.add(c.Email.toLowerCase());
            } else {
                keeperIndexes.add(i);
            }
        }

        if (checkIndexes.isEmpty()) {
            return;
        }

        // Single SOQL query for the whole execution. Rows that are part of this save are
        // skipped because their new values come from triggerNew.
        Set<String> storedKeys = new Set<String>();
        for (Contact existing : [
            SELECT Id, AccountId, Email
            FROM Contact
            WHERE AccountId IN :accountIds
            AND Email IN :emails
        ]) {
            if (existing.Id != null && batchIds.contains(existing.Id)) {
                continue;
            }
            String key = keyOf(existing.AccountId, existing.Email);
            if (key != null) {
                storedKeys.add(key);
            }
        }

        // Unchanged records claim their slots first, so changed records cannot take them.
        Set<String> claimedKeys = new Set<String>();
        for (Integer i : keeperIndexes) {
            Contact c = newContacts[i];
            String key = keyOf(c.AccountId, c.Email);
            if (key != null) {
                claimedKeys.add(key);
            }
        }

        // Checked records in list order: the first claimant wins, later ones are rejected.
        for (Integer i : checkIndexes) {
            Contact c = newContacts[i];
            String key = keyOf(c.AccountId, c.Email);
            if (key == null) {
                continue;
            }
            if (storedKeys.contains(key) || claimedKeys.contains(key)) {
                c.addError(DUPLICATE_EMAIL_MESSAGE);
            } else {
                claimedKeys.add(key);
            }
        }
    }

    private static String keyOf(Id accountId, String email) {
        if (accountId == null || String.isBlank(email)) {
            return null;
        }
        return String.valueOf(accountId) + '|' + email.toLowerCase();
    }
}
```

