/**
 * Trigger action that normalizes messy lead contact data on creation.
 * Runs in the before insert context, so the cleaned values are saved with the record.
 * Bulk-safe: loops over triggerNew once, with no SOQL and no DML.
 */
public class TA_Lead_NormalizeContactInfo implements TriggerAction.BeforeInsert {

    public void beforeInsert(List<SObject> triggerNew) {
        for (SObject so : triggerNew) {
            Lead ld = (Lead) so;

            // Email: trim and lower-case. A null email stays null.
            if (ld.Email != null) {
                ld.Email = ld.Email.trim().toLowerCase();
            }

            // Company: trim only. A null company stays null.
            if (ld.Company != null) {
                ld.Company = ld.Company.trim();
            }

            // LeadSource: default to 'Web' only when blank. Existing values are kept.
            if (String.isBlank(ld.LeadSource)) {
                ld.LeadSource = 'Web';
            }
        }
    }
}
