```apex
/**
 * Keeps Account.FB_Open_Case_Count__c equal to the number of the account's Cases
 * with IsClosed = false.
 *
 * Approach: collect every Account affected by the Case DML (old and new parent on
 * update, parent on insert/delete/undelete), then recount those accounts from the
 * database in one aggregate query. Recounting from the database rather than applying
 * deltas keeps the value correct for every event type and for bulk operations.
 *
 * Bulk budget per trigger execution: 2 SOQL (aggregate count + account read) and at most 1 DML.
 *
 * Declared without sharing so the recount sees all cases and can update the account
 * regardless of the running user's record access. This is system-maintained data.
 */
public without sharing class TA_Case_RollupOpenCount implements
        TriggerAction.AfterInsert,
        TriggerAction.AfterUpdate,
        TriggerAction.AfterDelete,
        TriggerAction.AfterUndelete {

    public void afterInsert(List<SObject> triggerNew) {
        Set<Id> accountIds = new Set<Id>();
        for (SObject s : triggerNew) {
            addId(accountIds, ((Case) s).AccountId);
        }
        recount(accountIds);
    }

    public void afterUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        Map<Id, Case> oldById = new Map<Id, Case>();
        for (SObject s : triggerOld) {
            oldById.put(s.Id, (Case) s);
        }

        Set<Id> accountIds = new Set<Id>();
        for (SObject s : triggerNew) {
            Case newCase = (Case) s;
            Case oldCase = oldById.get(newCase.Id);
            if (oldCase == null
                    || oldCase.AccountId != newCase.AccountId
                    || oldCase.IsClosed != newCase.IsClosed) {
                addId(accountIds, newCase.AccountId);
                if (oldCase != null) {
                    addId(accountIds, oldCase.AccountId);
                }
            }
        }
        recount(accountIds);
    }

    public void afterDelete(List<SObject> triggerOld) {
        Set<Id> accountIds = new Set<Id>();
        for (SObject s : triggerOld) {
            addId(accountIds, ((Case) s).AccountId);
        }
        recount(accountIds);
    }

    public void afterUndelete(List<SObject> triggerNew) {
        Set<Id> accountIds = new Set<Id>();
        for (SObject s : triggerNew) {
            addId(accountIds, ((Case) s).AccountId);
        }
        recount(accountIds);
    }

    private static void addId(Set<Id> accountIds, Id accountId) {
        if (accountId != null) {
            accountIds.add(accountId);
        }
    }

    /**
     * Recounts open cases for the given accounts and updates only those whose stored
     * value differs. Accounts with no open cases get 0, not null.
     * Accounts that no longer exist (e.g. deleted parents) are skipped by the account query.
     */
    private static void recount(Set<Id> accountIds) {
        if (accountIds.isEmpty()) {
            return;
        }

        // SOQL 1: open case counts. Accounts with no open cases are absent from the result.
        Map<Id, Integer> openByAccount = new Map<Id, Integer>();
        for (AggregateResult ar : [
                SELECT AccountId accId, COUNT(Id) openCount
                FROM Case
                WHERE AccountId IN :accountIds AND IsClosed = false
                GROUP BY AccountId
        ]) {
            openByAccount.put((Id) ar.get('accId'), (Integer) ar.get('openCount'));
        }

        // SOQL 2: existing accounts only (filters out deleted parents) and their stored value.
        List<Account> changed = new List<Account>();
        for (Account acc : [
                SELECT Id, FB_Open_Case_Count__c
                FROM Account
                WHERE Id IN :accountIds
        ]) {
            Integer expected = openByAccount.containsKey(acc.Id) ? openByAccount.get(acc.Id) : 0;
            if (acc.FB_Open_Case_Count__c != expected) {
                changed.add(new Account(Id = acc.Id, FB_Open_Case_Count__c = expected));
            }
        }

        // DML 1: single update, only when something actually changed.
        if (!changed.isEmpty()) {
            update changed;
        }
    }
}
```

