/**
 * Singleton that holds the parent Accounts for the Contacts in the current
 * trigger execution. The inner Service action runs first in before insert
 * (Order__c 1) and reloads the map on every execution, so one Account query
 * is shared by all Contact before-insert actions.
 */
public inherited sharing class TA_Contact_Queries {

    private static TA_Contact_Queries instance;

    public Map<Id, Account> accountsById = new Map<Id, Account>();

    private TA_Contact_Queries() {
    }

    public static TA_Contact_Queries getInstance() {
        if (instance == null) {
            instance = new TA_Contact_Queries();
        }
        return instance;
    }

    /**
     * Trigger action that loads the parent Accounts for all Contacts in
     * triggerNew. Registered with the lowest Order__c for before insert.
     */
    public class Service implements TriggerAction.BeforeInsert {

        public void beforeInsert(List<SObject> triggerNew) {
            Set<Id> accountIds = new Set<Id>();
            for (SObject so : triggerNew) {
                Id accountId = ((Contact) so).AccountId;
                if (accountId != null) {
                    accountIds.add(accountId);
                }
            }

            // One Account query per trigger execution. Reloaded every time because
            // earlier DML in the same transaction may involve other accounts.
            TA_Contact_Queries.getInstance().accountsById = new Map<Id, Account>();
            if (!accountIds.isEmpty()) {
                TA_Contact_Queries.getInstance().accountsById = new Map<Id, Account>(
                    [
                        SELECT Id, BillingStreet, BillingCity, BillingPostalCode, BillingCountry, AccountSource
                        FROM Account
                        WHERE Id IN :accountIds
                    ]
                );
            }
        }
    }
}
```

