/**
 * Before insert: when a new Contact has an Account and a blank LeadSource,
 * sets LeadSource to the Account's AccountSource.
 * Relies on TA_Contact_Queries.Service having loaded the parent accounts.
 */
public inherited sharing class TA_Contact_DefaultLeadSource implements TriggerAction.BeforeInsert {

    public void beforeInsert(List<SObject> triggerNew) {
        Map<Id, Account> accountsById = TA_Contact_Queries.getInstance().accountsById;

        for (SObject so : triggerNew) {
            Contact con = (Contact) so;

            if (con.AccountId == null || !accountsById.containsKey(con.AccountId)) {
                continue;
            }

            if (String.isNotBlank(con.LeadSource)) {
                continue;
            }

            Account parent = accountsById.get(con.AccountId);
            if (String.isNotBlank(parent.AccountSource)) {
                con.LeadSource = parent.AccountSource;
            }
        }
    }
}
